window.products.push({"id":213890,"name":"3-Pack Large Vacuum Packs","category":"homeandappliances","retail price":9.58,"sale price":null,"image":"https://m.media-amazon.com/images/I/71fDZRt9SgL._AC_SL1500_.jpg","description":"Dimensions: 21''W x 33.5''H VAC-01300 Vacuum-Packs are vacuum sealed storage bags designed for compacting and storing everything from seasonal clothing to linens. Simply place your items into the bag, attach any hose-style vacuum cleaner, and watch as the air is removed and items compress into a smaller, manageable pack.  These vacuum packs help protect your stored items from dirt, insects, and moisture keeping contents fresh and damage-free.","images":["https://m.media-amazon.com/images/I/71fDZRt9SgL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Honey-Can-Do","source_asin":"B003XARBC4","category_path":"Home & Kitchen"},"sku":"BM-213890","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B003XARBC4","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B003XARBC4","price_pending":true,"merchant_ready":false});
